.shell {
  width: 636px;
  height: 462px;
  position: relative;
  top: 0;
  left: 0;
  display: flex;
  flex-direction: column;
  overflow: hidden;
  border-radius: var(--mvu-radius-lg, 16px);
  border: 1px solid var(--mvu-color-line-muted, rgba(255, 255, 255, 0.1));
  background: var(--bg);
  backdrop-filter: var(--bg-blur);
  -webkit-backdrop-filter: var(--bg-blur);
  border: 1px solid var(--mvu-color-line-soft, rgba(255, 255, 255, 0.08));
  transform-origin: top left;
  box-shadow:
    inset 0 0 28px rgba(0, 229, 255, 0.04),
    0 20px 60px rgba(0, 0, 0, 0.45);
  clip-path: polygon(
    14px 0,
    calc(100% - 14px) 0,
    100% 14px,
    100% calc(100% - 14px),
    calc(100% - 14px) 100%,
    14px 100%,
    0 calc(100% - 14px),
    0 14px
  );
}

.shell::before {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  top: 0;
  height: 3px;
  background: var(--grad-top);
  z-index: 3;
}

.shell::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: auto;
  background:
    radial-gradient(circle at left top, rgba(255, 255, 255, 0.07), transparent 22%),
    radial-gradient(circle at right bottom, var(--mvu-color-gold-fill, rgba(255, 215, 0, 0.08)), transparent 24%);
  z-index: 0;
}

.ring-group {
  position: absolute;
  pointer-events: none;
  z-index: 0;
  opacity: 0.18;
}

.top-left-rings {
  top: -88px;
  left: -88px;
  width: 220px;
  height: 220px;
}
.bottom-right-rings {
  bottom: -84px;
  right: -84px;
  width: 220px;
  height: 220px;
}
.astro-circle {
  position: absolute;
  border-radius: 50%;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
}
.ring-cyan-1 {
  width: 100%;
  height: 100%;
  border: 2px dashed rgba(226, 233, 240, 0.82);
  animation: spin 16s linear infinite;
}
.ring-cyan-2 {
  width: 76%;
  height: 76%;
  border: 1px solid rgba(214, 223, 232, 0.52);
  animation: spin-reverse 19s linear infinite;
}
.ring-cyan-3 {
  width: 58%;
  height: 58%;
  border: 2px dotted rgba(214, 223, 232, 0.48);
  animation: spin 9s linear infinite;
}
.ring-gold-1 {
  width: 100%;
  height: 100%;
  border: 2px dashed var(--gold);
  animation: spin-reverse 16s linear infinite;
}
.ring-gold-2 {
  width: 76%;
  height: 76%;
  border: 1px solid rgba(255, 215, 0, 0.45);
  animation: spin 19s linear infinite;
}
.ring-gold-3 {
  width: 58%;
  height: 58%;
  border: 2px dotted rgba(255, 215, 0, 0.45);
  animation: spin-reverse 9s linear infinite;
}
@keyframes spin {
  100% {
    transform: translate(-50%, -50%) rotate(360deg);
  }
}
@keyframes spin-reverse {
  100% {
    transform: translate(-50%, -50%) rotate(-360deg);
  }
}

.header {
  position: relative;
  z-index: 1;
  padding: 6px 8px 6px;
  border-bottom: 1px solid rgba(0, 229, 255, 0.1);
  background: linear-gradient(90deg, rgba(0, 229, 255, 0.07), transparent 48%, rgba(255, 215, 0, 0.05));
}

.header-loc {
  min-width: 0;
  display: flex;
  align-items: flex-start;
  gap: 6px;
  font-family: var(--font-ui);
  font-size: var(--mvu-font-sm, 12px);
  font-weight: 600;
  line-height: 1.2;
  letter-spacing: 0.18px;
  color: #eefbff;
  white-space: normal;
  text-shadow:
    0 1px 3px rgba(0, 0, 0, 0.4),
    0 0 10px rgba(95, 233, 255, 0.08);
  opacity: 1;
}

.header-loc span {
  min-width: 0;
  white-space: normal;
  display: flex;
  flex-direction: column;
  gap: 3px;
}

.header-loc .mvu-header-time {
  color: #fff;
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.2;
}

.header-loc .mvu-header-location {
  color: rgba(238, 251, 255, 0.72);
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.2;
}

#detailModal .modal-title {
  text-rendering: geometricPrecision;
}

.header-loc svg {
  width: 14px;
  height: 14px;
  flex: 0 0 auto;
  color: var(--cyan);
}

.character-switch {
  min-width: 0;
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 7px 10px;
  border-radius: var(--mvu-radius-md, 12px);
  border: 1px solid rgba(0, 229, 255, 0.2);
  background: linear-gradient(180deg, rgba(0, 229, 255, 0.05), rgba(0, 229, 255, 0.02));
  cursor: pointer;
  transition: 0.18s ease;
}

.character-switch:hover {
  box-shadow: var(--shadow-cyan);
}

.char-emblem {
  width: 26px;
  height: 26px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  color: var(--gold);
  border: 1px solid rgba(255, 215, 0, 0.25);
  background: rgba(255, 215, 0, 0.07);
  font-size: var(--mvu-font-sm, 12px);
  flex: 0 0 auto;
}

.char-name {
  font-family: var(--font-title);
  font-size: var(--mvu-font-md, 14px);
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
}

.header-time {
  display: none;
}

.ghost-btn {
  appearance: none;
  border: 1px solid rgba(0, 229, 255, 0.24);
  background: rgba(0, 229, 255, 0.05);
  color: var(--cyan);
  border-radius: var(--mvu-radius-md, 12px);
  padding: 7px 10px;
  font-family: var(--font-tech);
  font-size: var(--mvu-font-xs, 10px);
  letter-spacing: 1px;
  cursor: pointer;
}

.stage {
  position: relative;
  z-index: 1;
  flex: 1;
  min-height: 0;
  padding: 5px 6px 4px;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.page {
  display: none;
  height: 100%;
  min-height: 0;
  overflow: hidden;
}

.page.active {
  display: flex;
  flex-direction: column;
  gap: 4px;
  animation: pageFrameIn 0.22s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.page.active > * {
  animation: pageBlockIn 0.28s cubic-bezier(0.22, 1, 0.36, 1) both;
}

.page.active > *:nth-child(2) {
  animation-delay: 0.04s;
}

.page.active > *:nth-child(3) {
  animation-delay: 0.08s;
}

