    radial-gradient(circle at 50% 44%, color-mix(in srgb, var(--主题主色) 6.5%, transparent), transparent 30%),
    linear-gradient(180deg, color-mix(in srgb, var(--暗场底板强) 48%, transparent), color-mix(in srgb, var(--暗场底板强) 82%, transparent));
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.035),
    inset 0 0 20px color-mix(in srgb, var(--主题主色) 4.5%, transparent),
    0 12px 28px rgba(0, 0, 0, 0.26);
  cursor: crosshair;
  isolation: isolate;
  touch-action: none;
}

.map-canvas.map-canvas-large::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 6;
  pointer-events: none;
  background:
    linear-gradient(color-mix(in srgb, var(--主题主色) 2.8%, transparent) 1px, transparent 1px),
    linear-gradient(90deg, color-mix(in srgb, var(--主题主色) 2%, transparent) 1px, transparent 1px),
    radial-gradient(circle at 50% 50%, transparent 54%, rgba(0, 8, 14, 0.44) 100%);
  background-size: 22px 22px, 22px 22px, 100% 100%;
  opacity: 0.58;
}

.map-canvas.dragging,
.map-canvas.is-editing {
  cursor: crosshair;
  user-select: none;
}

.map-canvas.dragging .map-world,
.map-canvas.map-transforming .map-world {
  will-change: transform;
}

.map-canvas.dragging .map-node-layer,
.map-canvas.map-transforming .map-node-layer {
  pointer-events: none;
}

.map-world,
.map-terrain,
.map-node-layer {
  position: absolute;
  inset: 0;
}

.map-world {
  z-index: 1;
  transform-origin: center center;
  backface-visibility: visible;
}

.map-terrain {
  z-index: 1;
  overflow: hidden;
  pointer-events: none;
  -webkit-user-drag: none;
  user-select: none;
}

.map-node-layer {
  z-index: 4;
  overflow: hidden;
}

.map-terrain-art,
.map-terrain-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  background-image: url("MAP.webp");
  background-repeat: no-repeat;
  background-position: center;
  background-size: 100% 100%;
}

.map-terrain-art {
  image-rendering: auto;
}

.map-terrain-svg {
  display: block;
  filter: saturate(1.02) contrast(1.03) brightness(0.96);
}

.map-terrain-mask {
  position: absolute;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(circle at 50% 46%, rgba(255, 255, 255, 0.055), transparent 30%),
    linear-gradient(180deg, rgba(255, 255, 255, 0.025), transparent 24%, rgba(0, 0, 0, 0.16));
}

.map-node {
  position: absolute;
  z-index: 4;
  display: block;
  padding: 0;
  border: 0;
  background: transparent;
  color: inherit;
  cursor: pointer;
  pointer-events: auto;
  transform: translate(-50%, -50%) scale(var(--node-ui-scale, 1));
  transform-origin: center center;
  transition:
    opacity 180ms ease,
    transform 180ms ease,
    filter 180ms ease;
}

.map-canvas.dragging .map-node,
.map-canvas.map-transforming .map-node {
  transition: none;
}

.map-node:hover,
.map-node.current,
.map-node.origin {
  z-index: 7;
  filter: brightness(1.08);
}

.map-node.is-hidden {
  opacity: 0;
  pointer-events: none;
}

.map-dot {
  position: relative;
  display: block;
  width: 5px;
  height: 5px;
  border: 1px solid rgba(6, 13, 20, 0.9);
  border-radius: 50%;
  background: #edf2f5;
  box-shadow:
    0 0 0 1px rgba(8, 14, 20, 0.52),
    0 1px 5px rgba(0, 0, 0, 0.3);
}

.map-dot.major,
.map-node.point-kind-settlement .map-dot {
  width: 7px;
  height: 7px;
  background: #d8bd72;
  box-shadow:
    0 0 0 1px rgba(38, 30, 16, 0.48),
    0 2px 7px rgba(0, 0, 0, 0.32);
}

.map-node.point-kind-terrain .map-dot {
  width: 4px;
  height: 4px;
  background: #8fcfe0;
  box-shadow:
    0 0 0 1px rgba(16, 32, 38, 0.42),
    0 1px 5px rgba(0, 0, 0, 0.26);
}

.map-node.point-kind-dynamic .map-dot {
  background: #d06a60;
}

.map-node.current .map-dot {
  background: #76e2ff;
  box-shadow:
    0 0 0 2px color-mix(in srgb, var(--边线颜色) 16%, transparent),
    0 0 13px color-mix(in srgb, var(--边线颜色) 46%, transparent);
}

.map-node.origin .map-dot {
  background: #ffd45f;
  box-shadow:
    0 0 0 2px rgba(255, 212, 95, 0.16),
    0 0 12px rgba(255, 212, 95, 0.4);
}

.map-node.state-ruins:not(.current):not(.origin) .map-dot {
  background: #cf6d64;
  border-color: rgba(86, 20, 20, 0.92);
}

.map-node.state-rebuild:not(.current):not(.origin) .map-dot {
  background: #d8bd72;
  border-color: rgba(92, 70, 20, 0.92);
}

.map-node.state-rebuilt:not(.current):not(.origin) .map-dot {
  background: #76c894;
  border-color: rgba(18, 68, 40, 0.9);
}

.map-node-label {
  position: absolute;
  left: calc(50% + var(--label-offset-x, 0px));
  top: calc(100% + 6px + var(--label-offset-y, 0px));
  max-width: clamp(68px, 16vw, 136px);
  padding: 2px 6px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 999px;
  background: rgba(5, 14, 23, 0.78);
  color: rgba(244, 252, 255, 0.94);
  font-size: 9px;
  line-height: 1.2;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  text-shadow: 0 0 8px rgba(0, 0, 0, 0.72);
  box-shadow: 0 5px 12px rgba(0, 0, 0, 0.22);
  transform: translateX(-50%);
}

.map-node:hover .map-node-label,
.map-node.current .map-node-label {
  border-color: color-mix(in srgb, var(--边线颜色) 28%, transparent);
  color: #ffffff;
  box-shadow:
    0 6px 16px rgba(0, 0, 0, 0.26),
    0 0 14px color-mix(in srgb, var(--边线颜色) 18%, transparent);
}

.map-node.point-kind-settlement .map-node-label {
  color: #fff2bf;
}

.map-node.state-ruins .map-node-label {
  color: rgba(255, 202, 194, 0.97);
}

.map-node.state-rebuild .map-node-label {
  color: rgba(255, 233, 181, 0.97);
}

.map-node.state-rebuilt .map-node-label {
  color: rgba(207, 248, 219, 0.97);
}

.map-node-enter-tag,
.map-node-state-tag {
  margin-left: 4px;
  font-size: 8px;
  font-weight: 800;
  opacity: 0.96;
}

.map-node-state-tag.is-ruins {
  color: rgba(255, 183, 171, 0.98);
}

.map-node-state-tag.is-rebuild {
  color: rgba(255, 224, 148, 0.98);
}

.map-node-state-tag.is-rebuilt {
  color: rgba(178, 245, 198, 0.98);
}

.map-hover-tooltip {
  position: absolute;
  z-index: 14;
  display: grid;
  gap: 3px;
  max-width: 180px;
  padding: 7px 9px;
  border: 1px solid color-mix(in srgb, var(--边线颜色) 22%, transparent);
  border-radius: 4px;
  background: rgba(5, 14, 23, 0.9);
  color: var(--map-panel-text);
  font-size: 10px;
  line-height: 1.25;
  box-shadow: 0 12px 28px rgba(0, 0, 0, 0.34);
  pointer-events: none;
  transform: translate(12px, 12px);
}

.map-hover-tooltip b {
  color: #ffffff;
  font: 700 10px/1 var(--font-mono, "Cascadia Code", Consolas, monospace);
  text-shadow: 0 0 8px color-mix(in srgb, var(--边线颜色) 36%, transparent);
}

.map-hover-tooltip span {
  color: var(--map-panel-muted);
}

.map-status-strip {
  display: grid;
  grid-template-columns: repeat(5, minmax(0, 1fr));
  gap: 6px;
  margin-top: 8px;
}

.map-status-chip {
  min-width: 0;
  padding: 7px 8px;
  border: 1px solid color-mix(in srgb, var(--边线颜色) 12%, transparent);
  border-radius: 4px;
  background: rgba(5, 14, 23, 0.44);
  box-shadow: inset 0 0 14px color-mix(in srgb, var(--边线颜色) 4%, transparent);
}

.map-status-chip b,
.map-status-chip span {
  display: block;
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.map-status-chip b {
  margin-bottom: 3px;
  color: rgba(204, 232, 242, 0.72);
  font-size: 10px;
  font-weight: 650;
}

.map-status-chip span {
  color: #ffffff;
  font-size: 11px;
  font-weight: 700;
  text-shadow: 0 0 8px color-mix(in srgb, var(--边线颜色) 28%, transparent);
}

.map-status-chip.live {
  border-color: color-mix(in srgb, var(--边线颜色) 20%, transparent);
}

.map-status-chip.gold {
  border-color: rgba(255, 212, 95, 0.2);
}

.mvu-holo-map-side-stack {
  display: flex;
  flex-direction: column;
  gap: 8px;
  min-width: 0;
  min-height: 0;
}

.mvu-holo-map-card {
  position: relative;
  min-width: 0;
  padding: 10px;
  border: 0;
  border-radius: 4px;
  background: var(--全息材质底);
  box-shadow:
    2px 4px 10px rgba(0, 0, 0, 0.3),
    inset 0 0 0 1px rgba(255, 255, 255, 0.075),
    inset 0 0 18px color-mix(in srgb, var(--主题主色) 6%, transparent);
  color: var(--map-panel-text);
  backdrop-filter: var(--玻璃滤镜);
  -webkit-backdrop-filter: var(--玻璃滤镜);
}

.mvu-holo-map-card-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  margin-bottom: 8px;
}

.mvu-holo-map-card-title {
  min-width: 0;
  overflow: hidden;
  color: #ffffff;
  font-size: 12px;
  font-weight: 850;
  line-height: 1.18;
  text-overflow: ellipsis;
  white-space: nowrap;
  text-shadow: 0 0 10px color-mix(in srgb, var(--边线颜色) 34%, transparent);
}

.map-side-badge {
  flex: 0 0 auto;
  max-width: 48%;
  overflow: hidden;
  padding: 3px 7px;
  border: 1px solid color-mix(in srgb, var(--边线颜色) 16%, transparent);
  border-radius: 999px;
  background: color-mix(in srgb, var(--边线颜色) 7%, transparent);
  color: #bff5ff;
  font-size: 10px;
  line-height: 1;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.map-side-badge.gold {
  border-color: rgba(255, 212, 95, 0.18);
  background: rgba(255, 212, 95, 0.08);
  color: #ffe7a6;
}

.map-layer-pills,
.map-event-strip,
.map-panel-mode-strip {
  display: flex;
  flex-wrap: wrap;
  gap: 6px;
  min-width: 0;
  margin-bottom: 8px;
}

.map-layer-pill,
.map-event-chip {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  padding: 5px 8px;
  border: 1px solid rgba(170, 210, 226, 0.12);
  border-radius: 999px;
  background: rgba(8, 20, 31, 0.62);
  color: rgba(224, 241, 248, 0.82);
  font-size: 10px;
  line-height: 1;
  white-space: nowrap;
  cursor: default;
}

.map-layer-pill[data-map-layer-pill],
.map-panel-mode-btn {
  cursor: pointer;
  transition:
    border-color 160ms ease,
    color 160ms ease,
    background 160ms ease;
}

.map-layer-pill[data-map-layer-pill]:hover,
.map-panel-mode-btn:hover,
.map-layer-pill.current,
.map-panel-mode-btn.current,
.map-event-chip.live {
  border-color: color-mix(in srgb, var(--边线颜色) 26%, transparent);
  background: color-mix(in srgb, var(--边线颜色) 10%, transparent);
  color: #f5fdff;
}

.map-event-chip.warn {
  border-color: rgba(255, 170, 118, 0.24);
  background: rgba(120, 49, 43, 0.42);
  color: #ffe1d8;
}

.mvu-holo-map-row-list {
  display: grid;
  gap: 6px;
  min-width: 0;
}

.mvu-holo-map-row {
  display: grid;
  grid-template-columns: minmax(56px, 76px) minmax(0, 1fr);
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding: 5px 0;
  border-bottom: 1px solid color-mix(in srgb, var(--边线颜色) 9%, transparent);
}

.mvu-holo-map-row b,
.mvu-holo-map-row span {
  min-width: 0;
  overflow: hidden;
  line-height: 1.25;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvu-holo-map-row b {
  color: rgba(204, 232, 242, 0.66);
  font-size: 10px;
  font-weight: 650;
}

.mvu-holo-map-row span {
  color: #f5fdff;
  font-size: 11px;
  text-align: right;
}

.map-left-route-card.map-command-card {
  container-name: map-action-card;
  container-type: inline-size;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 4px;
  min-width: 0;
  overflow: visible;
}

.map-action-control-row {
  display: grid;
  grid-template-columns: minmax(82px, 0.36fr) minmax(0, 1fr);
  align-items: stretch;
  gap: 6px;
  min-width: 0;
  margin-bottom: 1px;
}

.map-action-primary,
.map-action-select-wrap,
.map-action-detail-cell {
  min-width: 0;
  border: 0;
  border-bottom: 1px solid var(--原型弱分隔线);
  background: rgba(255, 255, 255, 0.025);
  color: #dcecf7;
  font: inherit;
  box-shadow: inset 0 0 0 1px rgba(255, 255, 255, 0.035);
}

.map-action-primary {
  appearance: none;
  -webkit-appearance: none;
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 5px;
  min-height: 24px;
  padding: 4px 6px;
  cursor: pointer;
  text-align: left;
}

.map-action-select-wrap,
.map-action-detail-cell {
  display: grid;
  align-items: center;
  align-content: center;
  padding: 4px 6px;
}

.map-action-select-wrap {
  grid-template-columns: auto minmax(0, 1fr);
  gap: 6px;
  position: relative;
  z-index: 2;
}

.map-action-detail-cell {
  grid-template-columns: auto minmax(0, 1fr);
  gap: 5px;
  position: relative;
  min-height: 23px;
}

.map-action-primary b,
.map-action-select-wrap b,
.map-action-detail-cell b {
  display: block;
  color: rgba(255, 255, 255, 0.65);
  font-size: 9px;
  font-weight: 700;
  line-height: 1;
  white-space: nowrap;
}

.map-action-primary span,
.map-action-detail-cell > span,
.map-action-select {
  min-width: 0;
  color: #ffffff;
  font-size: 10px;
  font-weight: 760;
  line-height: 1.18;
  text-shadow: 0 0 8px color-mix(in srgb, var(--主题主色) 32%, transparent);
}

.map-action-detail-cell > span {
  display: block;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.map-action-primary span,
.map-action-select {
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.map-action-select {
  appearance: none;
  -webkit-appearance: none;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 6px;
  width: 100%;
  border: 0;
  outline: none;
  background: transparent;
  font: inherit;
  text-align: left;
  cursor: pointer;
}

.map-action-select::after {
  content: "";
  flex: 0 0 auto;
  width: 5px;
  height: 5px;
  border-right: 1px solid color-mix(in srgb, var(--边线颜色) 72%, transparent);
  border-bottom: 1px solid color-mix(in srgb, var(--边线颜色) 72%, transparent);
  transform: rotate(45deg);
  opacity: 0.85;
}

.map-action-select > span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.map-action-select[aria-expanded="true"]::after {
  transform: translateY(2px) rotate(225deg);
}

.map-action-select.disabled,
.map-action-select:disabled {
  cursor: default;
  opacity: 0.5;
}

.map-action-menu {
  position: absolute;
  top: calc(100% + 5px);
  right: 0;
  z-index: 20;
  display: grid;
  gap: 2px;
  width: min(220px, max(148px, 100%));
  max-height: 150px;
  padding: 5px;
  overflow: auto;
  border: 1px solid var(--原型弱分隔线);
  border-radius: 4px;
  background: var(--原型暗玻浮层);
  box-shadow:
    0 18px 36px rgba(0, 0, 0, 0.42),
    inset 0 0 18px color-mix(in srgb, var(--主题主色) 4.5%, transparent);
  backdrop-filter: var(--玻璃滤镜);
  -webkit-backdrop-filter: var(--玻璃滤镜);
}

.map-action-menu.is-hidden {
  display: none;
}

.map-action-option {
  display: grid;
  gap: 2px;
  width: 100%;
  min-width: 0;
  padding: 5px 6px;
  border: 0;
  border-left: 2px solid transparent;
  border-radius: 3px;
  background: transparent;
  color: rgba(238, 250, 255, 0.92);
  font: inherit;
  font-size: 10px;
  font-weight: 740;
  line-height: 1.15;
  text-align: left;
  cursor: pointer;
}

.map-action-option span,
.map-action-option small {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.map-action-option small {
  color: rgba(180, 219, 232, 0.62);
  font-size: 9px;
  font-weight: 620;
}

.map-action-option:hover:not(:disabled),
.map-action-option:focus-visible,
.map-action-option.current {
  border-left-color: color-mix(in srgb, var(--边线颜色) 90%, transparent);
  background: color-mix(in srgb, var(--主题主色) 7.5%, transparent);
  color: #f6fdff;
  outline: none;
}

.map-action-option.disabled,
.map-action-option:disabled {
  cursor: default;
  opacity: 0.46;
}

.map-action-primary:hover:not(.disabled),
.map-action-primary:focus-visible,
.map-action-select-wrap:focus-within,
.map-method-select:hover:not(.disabled),
.map-method-select:focus-visible,
.map-action-detail-cell.is-actionable:hover,
.map-action-detail-cell.is-actionable:focus-visible {
  border-color: color-mix(in srgb, var(--边线颜色) 34%, transparent);
  background: color-mix(in srgb, var(--主题主色) 4%, transparent);
  outline: none;
}

.map-action-detail-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(0, 0.78fr) minmax(0, 1fr);
  gap: 5px;
  min-width: 0;
  overflow: visible;
}

.map-action-detail-row.has-method {
  grid-template-columns: repeat(2, minmax(0, 1fr));
  grid-template-rows: repeat(2, minmax(22px, auto));
}

.map-method-select,
.map-action-detail-cell.is-actionable {
  cursor: pointer;
}

.map-action-primary.disabled,
.map-action-detail-row.disabled,
.map-method-select.disabled {
  opacity: 0.5;
  cursor: default;
}

@container map-action-card (max-width: 340px) {
  .map-action-detail-row,
  .map-action-detail-row.has-method {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 4px 7px;
  }

  .map-action-detail-cell {
    grid-template-columns: minmax(0, 1fr);
    min-height: 24px;
    padding: 2px 0;
  }

  .map-action-detail-cell b {
    display: none;
  }

  .map-action-detail-cell > span {
    justify-content: center;
    text-align: center;
    font-size: 10px;
  }
}

.map-telemetry-pill {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  max-width: 100%;
  min-height: 17px;
  padding: 2px 6px;
  border-radius: 999px;
  background: color-mix(in srgb, var(--边线颜色) 7.5%, transparent);
  color: rgba(224, 246, 255, 0.9);
  font-size: 10px;
  line-height: 1;
  font-weight: 760;
  white-space: nowrap;
  box-shadow: inset 0 0 0 1px color-mix(in srgb, var(--边线颜色) 11%, transparent);
}

.map-telemetry-pill b {
  color: rgba(177, 220, 233, 0.72);
  font-size: 10px;
}

.map-telemetry-pill strong {
  color: #ecfdff;
  font-size: 10px;
  font-weight: 850;
}

.map-telemetry-pill.is-gain strong {
  color: #7dfad0;
}

.map-telemetry-pill.is-cost strong {
  color: #ffc78b;
}

.map-telemetry-pill.is-muted {
  background: rgba(171, 206, 219, 0.055);
  color: rgba(171, 206, 219, 0.66);
}

.map-telemetry-pill.is-time i {
  color: color-mix(in srgb, var(--边线颜色) 82%, transparent);
