  font-weight: 850;
}

.map-npc-list {
  display: flex;
  flex-direction: column;
  gap: 2px;
  min-height: 0;
  max-height: min(360px, 42vh);
  margin-top: 4px;
  overflow-y: auto;
  padding-right: 2px;
  scrollbar-width: thin;
