.mvu-tab-btn {
  appearance: none;
  border: none;
  background: transparent;
  color: var(--text-sub);
  font-family: var(--font-tech);
  font-size: var(--mvu-font-sm, 12px);
  font-weight: 700;
  letter-spacing: 1px;
  padding: 8px 2px;
  cursor: pointer;
  position: relative;
  overflow: hidden;
  transition: 0.22s cubic-bezier(0.22, 1, 0.36, 1);
}

.mvu-tab-btn::before {
  content: '';
  position: absolute;
  top: 0;
  bottom: 0;
  left: -32%;
  width: 22%;
  pointer-events: none;
  opacity: 0;
  background: linear-gradient(
    90deg,
    transparent,
    rgba(0, 229, 255, 0.02),
    rgba(0, 229, 255, 0.2),
    var(--mvu-color-panel-soft, rgba(255, 255, 255, 0.03)),
    transparent
  );
  transform: skewX(-18deg) translateX(-100%);
}

@keyframes tabSweep {
  0% {
    opacity: 0;
    transform: skewX(-18deg) translateX(-100%);
  }
  25% {
    opacity: 0.8;
  }
  100% {
    opacity: 0;
    transform: skewX(-18deg) translateX(420%);
  }
}

.mvu-tab-btn:hover {
  background: rgba(0, 229, 255, 0.05);
  color: var(--white);
}

.mvu-tab-btn:hover::before,
.mvu-tab-btn.active::before {
  animation: tabSweep 0.58s cubic-bezier(0.22, 1, 0.36, 1) 1;
}

.mvu-tab-btn.active {
  color: var(--cyan);
  text-shadow: 0 0 8px rgba(0, 229, 255, 0.28);
  background: linear-gradient(0deg, var(--mvu-color-cyan-fill, rgba(0, 229, 255, 0.08)), transparent);
}

.mvu-tab-btn.active::after {
  content: '';
  position: absolute;
  left: 0;
  right: 0;
  bottom: 0;
  height: 2px;
  background: var(--grad-top);
}

.mvu-modal-panel .modal-body::-webkit-scrollbar {
  width: 0;
  height: 0;
}

.split-right-page[data-target='page-map'] .mvu-holo-map-card {
  flex: 0 0 auto !important;
  min-height: 0 !important;
  overflow-y: visible !important;
  overflow-x: visible !important;
}

.split-right-page[data-target='page-map'] .mvu-holo-map-card:first-child {
  min-height: 280px;
}

