}

.skill-designer-filter-option + .skill-designer-filter-option {
  border-top: 1px solid rgba(120, 220, 255, 0.08);
}

.skill-designer-filter-option:hover {
  background: rgba(85, 210, 230, 0.08);
}

.skill-designer-filter-option input {
  width: 14px;
  height: 14px;
  accent-color: #65d9ef;
}

.skill-designer-chip-grid {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.skill-designer-fusion-mode-grid {
  grid-template-columns: minmax(180px, 0.42fr);
}

.skill-designer-fusion-participant-list {
  display: grid;
  gap: 10px;
}

.skill-designer-fusion-participant-row {
  display: grid;
  grid-template-columns: minmax(168px, 0.9fr) minmax(168px, 1fr) auto;
  gap: 10px;
  align-items: end;
  padding: 10px;
  border-radius: var(--mvu-radius-lg, 16px);
  border: 1px solid rgba(165, 214, 228, 0.11);
  background: rgba(5, 14, 24, 0.42);
}

.skill-designer-fusion-row-actions {
  display: flex;
  align-items: end;
  min-height: 44px;
}

.skill-designer-fusion-row-actions .tag-chip {
  min-height: 40px;
  border-radius: var(--mvu-radius-md, 12px);
  white-space: nowrap;
}

:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) button.tag-chip,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.clickable,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .clickable {
  cursor: pointer;
  transition:
    transform 180ms ease,
    background 180ms ease,
    border-color 180ms ease,
    box-shadow 180ms ease,
    opacity 180ms ease;
}

:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) button.tag-chip:hover,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.clickable:hover,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .clickable:hover {
  border-color: rgba(77, 240, 255, 0.24);
  background: rgba(77, 240, 255, 0.09);
}

:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) button.tag-chip:active,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.clickable:active,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .clickable:active {
  transform: translateY(1px);
}

:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.is-busy,
:where(#mvu-unified-mount, #detailModal, #page-map, .mvu-hover-card-floating--portal, .mvu-cultivation-target-mask) .tag-chip.is-short-lock {
  opacity: 0.58;
  pointer-events: none;
}

.skill-designer-fusion-actions {
  margin-left: 0;
  justify-content: flex-start;
}

.skill-designer-fusion-actions[hidden] {
  display: none !important;
}

.skill-designer-check-chip {
  position: relative;
  cursor: pointer;
  user-select: none;
}

.skill-designer-check-chip input {
  position: absolute;
  opacity: 0;
  pointer-events: none;
}

.skill-designer-check-chip span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 32px;
  padding: 7px 12px;
  border-radius: var(--mvu-radius-pill, 999px);
  border: 1px solid rgba(165, 214, 228, 0.14);
  background: rgba(186, 223, 235, 0.06);
  color: rgba(223, 236, 241, 0.8);
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.2;
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    color 0.18s ease,
    box-shadow 0.18s ease;
}

.skill-designer-check-chip.active span {
  border-color: rgba(123, 220, 239, 0.28);
  background: rgba(89, 186, 212, 0.16);
  color: rgba(245, 249, 250, 0.98);
  box-shadow: 0 0 0 1px rgba(123, 220, 239, 0.1) inset;
}

.skill-designer-check-chip.recommended span {
  border-color: rgba(198, 224, 232, 0.2);
  background: rgba(227, 239, 244, 0.08);
}

.skill-designer-preview-stack {
  display: grid;
  gap: 10px;
}

.skill-designer-summary-list {
  gap: 10px;
}

.skill-designer-summary-row {
  display: grid;
  gap: 5px;
  padding: 10px 14px;
  border-radius: 0;
  border: none;
  border-left: 2px solid color-mix(in srgb, var(--边线颜色) 46%, transparent);
  background: linear-gradient(90deg, color-mix(in srgb, var(--主题主色) 10%, transparent), transparent);
  position: relative;
}

.skill-designer-summary-row em {
  font-style: normal;
  font-size: var(--mvu-font-xs, 10px);
  font-family: monospace;
  text-transform: uppercase;
  line-height: 1.35;
  color: var(--全息标签文字);
  letter-spacing: 0.1em;
}

.skill-designer-summary-row span {
  display: block;
  font-size: var(--mvu-font-md, 14px);
  line-height: 1.55;
  color: #fff;
  text-shadow: var(--全息数值字影);
  white-space: normal;
  word-break: break-word;
}

.skill-designer-attribute-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(60px, 100%), 1fr));
  gap: 8px 10px;
  min-width: 0;
}

.skill-designer-attribute-cell {
  display: grid;
  gap: 2px;
  align-content: start;
  min-width: 0;
  padding: 0;
  color: #fff;
  text-shadow: var(--全息数值字影);
}

.skill-designer-attribute-cell b {
  font-size: var(--mvu-font-sm, 12px);
  font-weight: 500;
  color: var(--全息标签文字);
}

.skill-designer-attribute-cell strong {
  min-width: 0;
  font-size: var(--mvu-font-md, 14px);
  font-weight: 700;
  color: #fff;
  line-height: 1.22;
  overflow-wrap: anywhere;
  word-break: break-word;
  white-space: normal;
}

.skill-designer-trial-card > div {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.skill-designer-cost-panel {
  display: grid;
  gap: 8px;
  min-width: 0;
}

.skill-designer-trial-row {
  display: grid;
  grid-template-columns: minmax(112px, 1fr) minmax(64px, auto);
  gap: 8px;
  align-items: center;
  min-height: 32px;
  padding: 4px 0;
}

.skill-designer-trial-row em {
  position: relative;
  min-width: 0;
  color: var(--全息标签文字);
  overflow-wrap: anywhere;
  white-space: normal;
  line-height: 1.35;
}

.skill-designer-trial-row span {
  min-width: 64px;
  color: var(--全息数值文字);
  font-weight: bold;
  text-align: right;
  white-space: nowrap;
}

.skill-designer-cost-help {
  position: relative;
  display: inline-grid;
  place-items: center;
  width: 14px;
  height: 14px;
  margin-left: 4px;
  padding: 0;
  border: 1px solid color-mix(in srgb, var(--边线颜色) 40%, transparent);
  border-radius: 50%;
  background: color-mix(in srgb, var(--主题主色) 8%, transparent);
  color: var(--全息标签文字);
  font: 700 10px/1 ui-monospace, SFMono-Regular, Menlo, Consolas, monospace;
  vertical-align: 1px;
  cursor: help;
}

.skill-designer-cost-help::after {
  content: attr(data-cost-tip);
  position: absolute;
  z-index: 20;
  left: 50%;
  bottom: calc(100% + 8px);
  width: min(220px, 62vw);
  padding: 7px 9px;
  border: 1px solid color-mix(in srgb, var(--边线颜色) 24%, transparent);
  background: rgba(8, 18, 20, 0.96);
  color: rgba(226, 252, 255, 0.92);
  box-shadow: 0 8px 22px rgba(0, 0, 0, 0.34);
  font: 500 11px/1.45 "Microsoft YaHei", sans-serif;
  text-align: left;
  white-space: normal;
  overflow-wrap: break-word;
  transform: translate(-50%, 4px);
  opacity: 0;
  pointer-events: none;
  transition: opacity 0.16s ease, transform 0.16s ease;
}

.skill-designer-cost-help:hover::after,
.skill-designer-cost-help:focus-visible::after {
  opacity: 1;
  transform: translate(-50%, 0);
}

.skill-designer-cost-block {
  display: grid;
  gap: 6px;
  min-width: 0;
  padding: 0 0 6px;
  border-bottom: 1px dashed color-mix(in srgb, var(--边线颜色) 24%, transparent);
}

.skill-designer-cost-block > summary {
  list-style: none;
  cursor: pointer;
}

.skill-designer-cost-block > summary::-webkit-details-marker {
  display: none;
}

.skill-designer-cost-block > .skill-designer-trial-row {
  padding-bottom: 0;
}

.skill-designer-cost-block > summary.skill-designer-trial-row {
  padding-bottom: 0;
}

.skill-designer-cost-block > summary.skill-designer-trial-row em {
  display: inline-flex;
  align-items: center;
  gap: 4px;
}

.skill-designer-cost-block > summary.skill-designer-trial-row em::before {
  content: "▾";
  color: var(--全息标签文字);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1;
}

.skill-designer-cost-block:not([open]) > summary.skill-designer-trial-row em::before {
  content: "▸";
}

.skill-designer-cost-detail {
  display: grid;
  gap: 4px;
  min-width: 0;
  margin-left: 10px;
  padding-left: 10px;
  border-left: 1px solid color-mix(in srgb, var(--边线颜色) 20%, transparent);
}

.skill-designer-cost-detail-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) minmax(56px, auto);
  gap: 8px;
  align-items: center;
  min-height: 24px;
}

.skill-designer-cost-detail-row em {
  min-width: 0;
  color: rgba(160, 248, 255, 0.66);
  font-size: var(--mvu-font-sm, 12px);
  font-style: normal;
  overflow-wrap: anywhere;
  white-space: normal;
}

.skill-designer-cost-detail-row em small {
  display: block;
  margin-top: 1px;
  color: rgba(160, 248, 255, 0.46);
  font-size: var(--mvu-font-xs, 10px);
}

.skill-designer-cost-detail-row span {
  min-width: 56px;
  color: var(--全息数值文字);
  font-size: var(--mvu-font-base, 13px);
  font-weight: 700;
  text-align: right;
  text-shadow: var(--全息数值字影);
  white-space: nowrap;
}

@keyframes skill-designer-fade-in {
  from {
    opacity: 0;
    transform: translateY(4px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.skill-designer-fade-in {
  animation: skill-designer-fade-in 0.3s ease-out forwards;
}

@media (max-width: 760px) {
  .skill-designer-status-prototype-row > .mvu-editor-field-grid[data-skill-designer-prototype-fields] {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }
  .skill-designer-remove-btn {
    width: 32px;
    height: 32px;
    font-size: var(--mvu-font-xl, 18px);
    top: 4px;
    right: 4px;
  }
}

.skill-designer-trial-row.muted span {
  color: rgba(190, 214, 222, 0.78);
  font-weight: 560;
}

.skill-designer-cost-detail-row.muted em,
.skill-designer-cost-detail-row.muted span {
  color: rgba(190, 214, 222, 0.66);
  text-shadow: none;
}

/* 空状态引导 HUD 样式 */

/* Skill Designer Vue */
.skill-designer-vue-host {
  --skill-designer-vue-bg: var(--主题底色, #06111e);
  --skill-designer-vue-shell: color-mix(in srgb, var(--暗场底板, rgba(5, 12, 18, 0.92)) 88%, var(--主题底色, #06111e));
  --skill-designer-vue-editor: color-mix(in srgb, var(--暗场卡片, rgba(9, 17, 24, 0.94)) 86%, var(--主题底色, #06111e));
  --skill-designer-vue-control-bg: color-mix(in srgb, var(--暗场底板强, rgba(8, 15, 22, 0.96)) 92%, var(--主题底色, #06111e));
  --skill-designer-vue-popover-bg: color-mix(in srgb, var(--暗场浮层, rgba(6, 12, 18, 0.98)) 94%, var(--主题底色, #06111e));
  --skill-designer-vue-surface: var(--skill-designer-vue-editor);
  --skill-designer-vue-surface-raised: var(--skill-designer-vue-shell);
  --skill-designer-vue-surface-floating: var(--skill-designer-vue-popover-bg);
  --skill-designer-vue-border: var(--虚线, rgba(118, 226, 255, 0.18));
  --skill-designer-vue-border-strong: var(--边线颜色, rgba(103, 247, 239, 0.32));
  --skill-designer-vue-text: var(--文字主色, #ffffff);
  --skill-designer-vue-muted: color-mix(in srgb, var(--文字主色, #ffffff) 72%, var(--文字弱色, #8ab4f8) 28%);
  --skill-designer-vue-accent: var(--主题主色, #67f7ef);
  --skill-designer-vue-accent-text: var(--主题高光, #ffffff);
  --skill-designer-vue-focus: var(--主题高光, #ffffff);
  --skill-designer-vue-accent-secondary: color-mix(in srgb, var(--主题主色, #67f7ef) 58%, var(--主题辅色, #101d27));
  --skill-designer-vue-relation: var(--主题主色, #67f7ef);
  --skill-designer-vue-danger: var(--状态危险色, #ff6b7a);
  --skill-designer-vue-success: var(--状态强调色, #7df9ff);
  --skill-designer-vue-warning: var(--主题高光, #ffffff);
  --skill-designer-vue-radius: min(8px, max(4px, var(--卡片圆角, 6px)));
  --skill-designer-vue-shell-cut: none;
  --skill-designer-vue-shell-texture: var(--背景细纹, none);
  --skill-designer-vue-heading-weight: var(--主题字重, 650);
  --skill-designer-vue-body-weight: var(--主题字重, 500);
  --skill-designer-vue-theme: var(--主题主色, #67f7ef);
  width: 100%;
  min-width: 0;
  container: skill-designer-vue / inline-size;
  color: var(--skill-designer-vue-text);
