  overflow: hidden;
}

.figure-board::before {
  content: '';
  position: absolute;
  left: 50%;
  top: 16px;
  bottom: 16px;
  width: 2px;
  transform: translateX(-50%);
  background: var(--mvu-color-line-soft, rgba(255, 255, 255, 0.08));
  border-radius: var(--mvu-radius-pill, 999px);
}

.figure-core {
  position: absolute;
  left: 50%;
  top: 50%;
  transform: translate(-50%, -50%);
  width: 70px;
  height: 104px;
  border-radius: var(--mvu-radius-pill, 999px);
  border: 1px solid rgba(0, 229, 255, 0.16);
  background: rgba(0, 229, 255, 0.05);
  box-shadow: inset 0 0 14px rgba(0, 229, 255, 0.04);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: var(--mvu-font-xs, 10px);
  color: var(--text-sub);
  text-align: center;
  padding: 6px;
  line-height: 1.3;
}

