.figure-slot.clickable {
  cursor: pointer;
  transition: 0.18s ease;
}

.figure-core.clickable:hover,
.figure-slot.clickable:hover {
  border-color: rgba(0, 229, 255, 0.28);
  box-shadow: var(--shadow-cyan);
}

.figure-slot {
  position: absolute;
  transform: translate(-50%, -50%);
  min-width: 68px;
  padding: 6px 7px;
  border-radius: var(--mvu-radius-pill, 999px);
  border: 1px solid var(--mvu-color-line-soft, rgba(255, 255, 255, 0.08));
  background: rgba(7, 16, 30, 0.9);
