}

.mvu-inventory-inspector-head.qual-legendary,
.inventory-definition-current.qual-legendary {
  border-color: rgba(251, 192, 45, 0.45);
  box-shadow: 0 0 8px rgba(251, 192, 45, 0.18);
}

.mvu-inventory-inspector-head.qual-artifact,
.inventory-definition-current.qual-artifact {
  border-color: rgba(211, 47, 47, 0.5);
  background: linear-gradient(90deg, rgba(70, 0, 0, 0.22), rgba(0, 0, 0, 0.1));
}

.mvu-inventory-inspector-head.qual-super,
.inventory-definition-current.qual-super {
  border-color: rgba(183, 196, 204, 0.34);
  background: linear-gradient(90deg, rgba(0, 0, 0, 0.46), rgba(38, 24, 48, 0.16), transparent);
  box-shadow: inset 0 0 18px rgba(0, 0, 0, 0.3);
}

.mvu-inventory-inspector-scroll {
  display: grid;
  gap: 10px;
  min-height: 0;
  max-height: none;
  overflow: auto;
  padding: 0 12px 12px;
}

.mvu-inventory-param-list {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 8px;
}

.mvu-inventory-param-row {
  display: grid;
  grid-template-columns: minmax(0, 0.72fr) minmax(0, 1.28fr);
  gap: 8px;
  align-items: start;
  min-width: 0;
  padding: 10px;
  border-bottom: 1px solid rgba(223, 246, 255, 0.07);
  background: rgba(4, 15, 24, 0.26);
  border-radius: 0;
}

.mvu-inventory-param-row span {
  font-size: var(--mvu-font-sm, 12px);
  color: rgba(223, 247, 255, 0.58);
  line-height: 1.45;
}

.mvu-inventory-param-row b {
  justify-self: end;
  text-align: right;
  font-size: var(--mvu-font-base, 13px);
  line-height: 1.4;
  color: var(--white);
  word-break: break-word;
}

.quality-value {
  color: var(--qual-common);
  font-weight: 800;
}

.quality-value.qual-common {
  color: var(--qual-common);
}

.quality-value.qual-uncommon {
  color: var(--qual-uncommon);
}

.quality-value.qual-rare {
  color: var(--qual-rare);
  text-shadow: 0 0 4px rgba(2, 136, 209, 0.36);
}

.quality-value.qual-epic {
  color: var(--qual-epic);
  text-shadow: 0 0 5px rgba(142, 36, 170, 0.36);
}

.quality-value.qual-legendary {
  color: var(--qual-legendary);
  text-shadow: 0 0 5px rgba(251, 192, 45, 0.32);
}

.quality-value.qual-artifact {
  color: var(--qual-artifact);
  text-shadow: 0 0 4px rgba(211, 47, 47, 0.34);
}

.quality-value.qual-super {
  color: var(--qual-super);
  text-shadow:
    0 0 4px rgba(2, 136, 209, 0.28),
    0 0 8px rgba(142, 36, 170, 0.22);
}

.mvu-inventory-param-row[data-field='品质'] .quality-value {
  letter-spacing: 0;
}

.inventory-detail-quote {
  margin: 0;
  padding: 10px 12px 10px 14px;
  border-left: 3px solid color-mix(in srgb, var(--边线颜色) 44%, transparent);
  border-radius: 8px;
  background: color-mix(in srgb, var(--主题主色) 5%, transparent);
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.6;
  color: rgba(223, 247, 255, 0.86);
}

.inventory-filter-row {
  display: flex;
  flex-wrap: wrap;
  gap: 4px;
  margin-bottom: 8px;
}

.inventory-instance-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
  margin-left: auto;
}

.inventory-definition-select-row {
  display: grid;
  grid-template-columns: minmax(0, 1fr) auto auto;
  gap: 8px;
  align-items: center;
  margin: 0 0 10px;
}

.inventory-definition-current,
.mvu-inventory-console-head,
.mvu-inventory-console-footer {
  position: relative;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  border: 1px solid var(--全息材质弱线);
  background: var(--全息材质底);
  padding: 10px;
}

.inventory-definition-current {
  margin-bottom: 10px;
}

.inventory-definition-current b,
.inventory-definition-current span {
  display: block;
}

.inventory-definition-current span {
  margin-top: 3px;
  font-size: var(--mvu-font-sm, 12px);
  color: rgba(223, 247, 255, 0.62);
}

.mvu-inventory-console-head {
  flex: 0 0 auto;
  border-radius: var(--mvu-radius-sm, 8px) var(--mvu-radius-sm, 8px) 0 0;
}

.mvu-inventory-console-footer {
  flex: 0 0 auto;
  border-radius: 0 0 var(--mvu-radius-sm, 8px) var(--mvu-radius-sm, 8px);
}

.inventory-console-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
}

.inventory-definition-subtitle {
  margin-top: 4px;
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.35;
  color: rgba(223, 247, 255, 0.62);
  overflow-wrap: anywhere;
}

.inventory-definition-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
  margin-left: auto;
}

.inventory-action-toolbar {
  position: relative;
  z-index: 2;
  display: flex;
  flex-wrap: wrap;
  justify-content: flex-end;
  gap: 6px;
  padding: 10px 12px 12px;
  margin-top: auto;
  border-top: 1px solid rgba(223, 246, 255, 0.08);
  background: rgba(4, 15, 24, 0.62);
}

.inventory-action-toolbar .tag-chip,
.inventory-action-toolbar .inventory-hover-action-btn {
  min-height: 28px;
  padding: 4px 10px;
  border-radius: var(--mvu-radius-pill, 999px);
}

.inventory-action-danger {
  border-color: rgba(255, 77, 122, 0.22);
  color: #ff9bb3;
  background: rgba(255, 77, 122, 0.07);
}

.item-definition-form-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 12px;
}

.item-definition-form-grid {
  margin-top: 0;
}

.item-definition-kv-list,
.item-definition-effect-list,
.item-definition-side-effect-list,
.item-definition-skill-list {
  display: grid;
  gap: 8px;
  padding: 10px;
  border: 1px solid rgba(0, 243, 255, 0.1);
  background: rgba(0, 0, 0, 0.2);
  border-radius: var(--mvu-radius-sm, 8px);
}

.item-definition-kv-row,
.item-definition-effect-row,
.item-definition-skill-row {
  display: grid;
  gap: 8px;
  align-items: center;
}

.item-definition-kv-row {
  grid-template-columns: minmax(90px, 0.8fr) minmax(120px, 1fr) auto;
}

.item-definition-effect-row {
  grid-template-columns:
    minmax(110px, 0.9fr) minmax(90px, 0.7fr) minmax(110px, 0.8fr) minmax(90px, 0.7fr) minmax(140px, 1.2fr)
    auto;
}

.item-definition-skill-row {
  grid-template-columns: minmax(120px, 1fr) auto;
}

.item-definition-side-effect-list .skill-designer-side-effect-row {
  position: relative;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(120px, 1fr));
  gap: 8px;
  align-items: end;
  padding: 10px 42px 10px 10px;
  border: 1px solid rgba(164, 221, 234, 0.12);
  border-left: 3px solid rgba(245, 186, 92, 0.32);
  border-radius: var(--mvu-radius-md, 12px);
  background: rgba(7, 31, 42, 0.24);
}

.item-definition-side-effect-list .skill-designer-side-effect-summary,
.item-definition-side-effect-list [data-skill-designer-side-effect-link-field] {
  grid-column: 1 / -1;
}

.item-definition-desc {
  min-height: 88px;
}

.item-definition-accordion {
  border: 1px solid rgba(0, 243, 255, 0.1);
  background: rgba(0, 0, 0, 0.16);
  border-radius: var(--mvu-radius-sm, 8px);
  overflow: hidden;
}

.item-definition-accordion summary {
  cursor: pointer;
  list-style: none;
  padding: 10px 12px;
  font-size: var(--mvu-font-sm, 12px);
  font-weight: 800;
  color: rgba(223, 247, 255, 0.9);
  border-bottom: 1px solid rgba(223, 246, 255, 0.08);
}

.item-definition-accordion summary::-webkit-details-marker {
  display: none;
}

.item-definition-module-body {
  display: grid;
  gap: 10px;
  padding: 12px;
}

.item-definition-subblock {
  display: grid;
  gap: 8px;
}

.item-definition-icon-btn {
  min-width: 32px;
  width: 32px;
  height: 32px;
  padding: 0;
}

.item-definition-quantity-field {
  max-width: 160px;
  margin-right: auto;
}

.mvu-inventory-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(150px, 1fr));
  gap: 8px;
  align-content: start;
}

.archive-tile-grid {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 8px;
}

.archive-tile {
  position: relative;
  z-index: 1;
  min-width: 0;
  padding: 7px 8px !important;
  transition: 0.18s ease;
}

.archive-tile.clickable {
  cursor: pointer;
  transform-style: preserve-3d;
}

.archive-tile.clickable:hover {
  transform: translateX(4px);
}

.archive-tile.clickable > * {
  transition: transform 0.24s var(--原型悬浮曲线);
}

.archive-tile.clickable:hover > * {
  transform: translateZ(var(--视差浮出深度));
}

.armory-quick-actions {
  align-items: center;
  gap: 8px;
}

.archive-tile-grid.compact {
  max-width: 320px;
}

.archive-tile-grid.compact .archive-tile {
  min-height: 44px;
  padding: 7px 8px;
}

.archive-tile-grid--compact-intel {
  grid-template-columns: minmax(0, 2.2fr) minmax(min(120px, 100%), 0.8fr);
  gap: 12px;
}

.archive-tile.archive-tile--compact-intel {
  min-height: 0;
  padding: 12px 14px !important;
}

.archive-tile-value--compact-intel {
  line-height: 1.7 !important;
}

.inventory-scroll-shell {
  position: relative;
  z-index: 1;
  min-height: 0;
  max-height: none;
  overflow-y: auto;
  overflow-x: hidden;
  padding-right: 4px;
  scrollbar-width: thin;
  scrollbar-color: rgba(121, 207, 238, 0.52) rgba(223, 246, 255, 0.08);
}

.inventory-scroll-shell::-webkit-scrollbar {
  width: 8px;
}

.inventory-scroll-shell::-webkit-scrollbar-track {
  background: rgba(223, 246, 255, 0.08);
  border-radius: var(--mvu-radius-pill, 999px);
}

.inventory-scroll-shell::-webkit-scrollbar-thumb {
  background: rgba(121, 207, 238, 0.52);
  border-radius: var(--mvu-radius-pill, 999px);
}

.inventory-cell {
  --仓库品质光色: rgba(223, 246, 255, 0.24);
  min-height: 86px;
  position: relative;
  isolation: isolate;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  padding: 10px 9px 8px;
  border-radius: var(--mvu-radius-sm, 8px);
  border: 1px solid rgba(223, 246, 255, 0.08);
  background:
    radial-gradient(circle at 100% 0%, var(--仓库品质光色), transparent 46%),
    linear-gradient(180deg, rgba(223, 246, 255, 0.07), rgba(10, 21, 32, 0.38));
  cursor: pointer;
  overflow: hidden;
  transition:
    transform 0.16s ease,
    box-shadow 0.16s ease,
    border-color 0.16s ease,
    background 0.16s ease;
}

.inventory-cell:hover {
  transform: translateY(-2px);
  box-shadow:
    0 14px 24px rgba(0, 0, 0, 0.18),
    0 0 18px var(--仓库品质光色),
    inset 0 0 14px rgba(223, 246, 255, 0.06);
  border-color: var(--仓库品质光色);
}

.inventory-cell::before,
.inventory-cell::after {
  content: '';
  position: absolute;
  pointer-events: none;
}

.inventory-cell::before {
  inset: 0;
  z-index: 0;
  opacity: 0.28;
  background: linear-gradient(135deg, transparent 0%, rgba(255, 255, 255, 0.04) 48%, transparent 72%);
}

.inventory-cell::after {
  z-index: 0;
}

.inventory-cell .cell-top {
  position: relative;
  z-index: 1;
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  gap: 4px;
  align-items: start;
  padding-right: 38px;
}

.inventory-cell .cell-top b {
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.28;
  color: var(--white);
  font-weight: 700;
  overflow: visible;
  overflow-wrap: anywhere;
  word-break: break-word;
}

.inventory-cell .qty {
  z-index: 2;
  position: absolute;
  top: 7px;
  right: 7px;
  max-width: 100%;
  font-size: var(--mvu-font-xs, 10px);
  color: #ffd700;
  border-radius: var(--mvu-radius-pill, 999px);
  padding: 2px 7px;
  background: rgba(255, 215, 0, 0.14);
  border: 1px solid rgba(255, 215, 0, 0.34);
  box-shadow:
    0 0 10px rgba(255, 215, 0, 0.22),
    inset 0 0 8px rgba(255, 215, 0, 0.08);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.inventory-cell .tier {
  position: relative;
  z-index: 1;
  margin-top: auto;
  padding-top: 5px;
  font-size: var(--mvu-font-xs, 10px);
  color: var(--text-sub);
  line-height: 1.3;
  border-top: 1px solid rgba(255, 255, 255, 0.06);
}

.inventory-cell.qual-common {
  --仓库品质光色: rgba(223, 246, 255, 0.22);
  background:
    radial-gradient(circle at 100% 0%, rgba(223, 246, 255, 0.12), transparent 46%),
    linear-gradient(180deg, rgba(223, 246, 255, 0.07), rgba(10, 21, 32, 0.38));
}

.inventory-cell.qual-uncommon {
  --仓库品质光色: rgba(67, 160, 71, 0.34);
  background:
    radial-gradient(circle at 100% 0%, rgba(67, 160, 71, 0.18), transparent 48%),
    linear-gradient(180deg, rgba(67, 160, 71, 0.07), rgba(10, 21, 32, 0.4));
}

.inventory-cell.qual-uncommon:hover {
  box-shadow:
    0 14px 24px rgba(0, 0, 0, 0.18),
    0 0 18px rgba(67, 160, 71, 0.22),
    inset 0 0 10px rgba(67, 160, 71, 0.12);
}

.inventory-cell.qual-rare {
  --仓库品质光色: rgba(2, 136, 209, 0.42);
  background:
    radial-gradient(circle at 100% 0%, rgba(2, 136, 209, 0.22), transparent 50%),
    linear-gradient(145deg, rgba(2, 136, 209, 0.12), rgba(10, 21, 32, 0.42) 58%);
}

.inventory-cell.qual-epic {
  --仓库品质光色: rgba(142, 36, 170, 0.44);
  background:
    radial-gradient(circle at 100% 0%, rgba(142, 36, 170, 0.24), transparent 52%),
    linear-gradient(180deg, rgba(142, 36, 170, 0.09), rgba(10, 21, 32, 0.42));
  box-shadow: 0 0 8px rgba(142, 36, 170, 0.18);
}

.inventory-cell.qual-legendary {
  --仓库品质光色: rgba(251, 192, 45, 0.46);
  background:
    radial-gradient(circle at 100% 0%, rgba(251, 192, 45, 0.25), transparent 52%),
    linear-gradient(180deg, rgba(251, 192, 45, 0.1), rgba(10, 21, 32, 0.42));
  box-shadow: 0 0 10px rgba(251, 192, 45, 0.18);
}

.inventory-cell.qual-legendary::before {
  background: radial-gradient(circle at center, rgba(251, 192, 45, 0.28), transparent 68%);
  animation: 背包传说呼吸 4.8s ease-in-out infinite;
}

.inventory-cell.qual-artifact {
  --仓库品质光色: rgba(211, 47, 47, 0.48);
  border-color: rgba(211, 47, 47, 0.22);
  background:
    radial-gradient(circle at 100% 0%, rgba(211, 47, 47, 0.24), transparent 52%),
    linear-gradient(180deg, rgba(65, 0, 0, 0.18), rgba(10, 21, 32, 0.48));
  box-shadow: inset 0 0 10px rgba(211, 47, 47, 0.08);
}

.inventory-cell.qual-artifact::before {
  background: radial-gradient(circle at center, rgba(211, 47, 47, 0.16), transparent 70%);
  animation: 背包神器呼吸 5.6s ease-in-out infinite;
}

.inventory-cell.qual-super {
  --背包超神器角度: 0deg;
  --仓库品质光色: rgba(183, 196, 204, 0.42);
  border-color: rgba(183, 196, 204, 0.18);
  background:
    radial-gradient(circle at 100% 0%, rgba(183, 196, 204, 0.16), transparent 50%),
    conic-gradient(from var(--背包超神器角度), rgba(43, 157, 169, 0.18), rgba(83, 45, 112, 0.18), rgba(150, 122, 48, 0.16), rgba(43, 157, 169, 0.18)),
    linear-gradient(180deg, rgba(1, 2, 5, 0.84), rgba(10, 21, 32, 0.5));
  box-shadow: inset 0 0 14px rgba(0, 0, 0, 0.42);
  animation: 背包超神器边缘 8s linear infinite;
}

.inventory-cell.qual-super::before {
  background: radial-gradient(circle at 50% 45%, rgba(224, 224, 224, 0.12), transparent 62%);
  opacity: 0.22;
}

.inventory-cell.is-selected {
  border-color: var(--仓库品质光色);
  background:
    radial-gradient(circle at 100% 0%, var(--仓库品质光色), transparent 48%),
    linear-gradient(180deg, rgba(223, 246, 255, 0.09), rgba(10, 21, 32, 0.46));
  animation: 仓库物品选中呼吸 1.8s ease-in-out infinite;
}

@property --背包超神器角度 {
  syntax: '<angle>';
  inherits: false;
  initial-value: 0deg;
}

@keyframes 背包传说呼吸 {
  0%,
  100% {
    opacity: 0.1;
  }
  50% {
    opacity: 0.3;
  }
}

@keyframes 背包神器呼吸 {
  0%,
  100% {
    opacity: 0.12;
  }
  50% {
    opacity: 0.24;
  }
}

@keyframes 背包超神器边缘 {
  to {
    --背包超神器角度: 360deg;
  }
}

@keyframes 仓库物品选中呼吸 {
  0%,
  100% {
    box-shadow:
      0 0 0 1px var(--仓库品质光色),
      0 0 12px var(--仓库品质光色),
      inset 0 0 14px rgba(223, 246, 255, 0.07);
  }
  50% {
    box-shadow:
      0 0 0 1px var(--仓库品质光色),
      0 0 22px var(--仓库品质光色),
      inset 0 0 20px rgba(223, 246, 255, 0.11);
  }
}

.inventory-hover-panel {
  position: fixed;
  z-index: var(--mvu-z-popover, 10060);
  width: 236px;
  max-width: calc(100vw - 24px);
  max-height: min(360px, calc(100svh - 32px));
  overflow-y: auto;
  padding: 9px 10px;
  border-radius: var(--mvu-radius-lg, 16px);
  border: 1px solid var(--全息材质线);
  background: var(--全息材质底);
  box-shadow:
    0 18px 36px rgba(0, 0, 0, 0.34),
    var(--全息材质阴影);
  backdrop-filter: var(--玻璃滤镜);
  -webkit-backdrop-filter: var(--玻璃滤镜);
  pointer-events: auto;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.1s ease;
}

.inventory-hover-panel.show {
  opacity: 1;
  visibility: visible;
}

.inventory-hover-panel::before {
  content: '';
  position: absolute;
  width: 10px;
  height: 10px;
  left: 16px;
  top: -5px;
  transform: rotate(45deg);
  background: var(--暗场卡片);
  border-left: 1px solid var(--全息材质线);
  border-top: 1px solid var(--全息材质线);
}

.inventory-hover-panel.flip-y::before {
  top: auto;
  bottom: -5px;
  border-left: none;
  border-top: none;
  border-right: 1px solid var(--全息材质线);
  border-bottom: 1px solid var(--全息材质线);
}

.inventory-hover-title {
  font-family: var(--font-title);
  font-size: var(--mvu-font-md, 14px);
  color: var(--white);
  line-height: 1.35;
  margin-bottom: 7px;
}

.inventory-hover-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 6px;
  margin-bottom: 7px;
}

.inventory-hover-grid .meta-item {
  min-height: 0;
  padding: 6px 7px;
}

.inventory-hover-grid .meta-item b {
  font-size: var(--mvu-font-xs, 10px);
  margin-bottom: 3px;
}

.inventory-hover-grid .meta-item span {
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.3;
}

.inventory-hover-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 5px;
}

@media (max-width: 860px) {
  .mvu-inventory-workbench,
  .inventory-definition-layout,
  .inventory-definition-layout.is-editor-open,
  .item-definition-form-grid,
  .item-definition-section-grid {
    grid-template-columns: 1fr;
  }

  .inventory-definition-select-row,
  .item-definition-kv-row,
  .item-definition-effect-row,
  .item-definition-skill-row {
    grid-template-columns: 1fr;
  }

  .inventory-definition-actions {
    width: 100%;
    justify-content: flex-start;
  }

  .mvu-inventory-param-list {
    grid-template-columns: 1fr;
  }

  .wallet-strip {
    grid-template-columns: repeat(2, minmax(0, 1fr));
