/* =========================================================================
   Hologram Layout Root: capacity-based aligned dashboard
   ========================================================================= */
:root {
  /* z-index scale */
  --mvu-z-hud: 1000;
  --mvu-z-overlay: 1100;
  --mvu-z-modal: 10050;
  --mvu-z-popover: 10060;
  --mvu-z-toast: 10070;

  /* radius scale */
  --mvu-radius-xs: 4px;
  --mvu-radius-sm: 8px;
  --mvu-radius-md: 12px;
  --mvu-radius-lg: 16px;
  --mvu-radius-xl: 20px;
  --mvu-radius-pill: 999px;

  /* shadow scale */
  --mvu-shadow-sm: 0 4px 10px rgba(0, 0, 0, 0.12);
  --mvu-shadow-md: 0 8px 18px rgba(0, 0, 0, 0.16);
  --mvu-shadow-lg: 0 22px 44px rgba(0, 0, 0, 0.26);
  --mvu-shadow-xl: 0 28px 72px rgba(0, 0, 0, 0.46);
  --mvu-shadow-glow: 0 0 24px rgba(118, 226, 255, 0.18);

  /* font size scale */
  --mvu-font-xs: 10px;
  --mvu-font-sm: 12px;
  --mvu-font-base: 13px;
  --mvu-font-md: 14px;
  --mvu-font-lg: 16px;
  --mvu-font-xl: 18px;
  --mvu-font-2xl: 22px;

  /* breakpoints (used by JS via getComputedStyle if needed) */
  --mvu-bp-sm: 640px;
  --mvu-bp-md-small: 760px;
  --mvu-bp-md: 860px;
  --mvu-bp-lg: 1180px;
}

body.mvu-layout-holo #mvu-unified-mount {
  --mvu-hud-frame-height: clamp(480px, calc(100svh - 220px), var(--mvu-unified-frame-max-height, 660px));
  --mvu-hud-gap: 6px;
  --mvu-hud-card-pad: 9px;
  --mvu-hud-radius: 14px;
  --mvu-hud-line: rgba(118, 226, 255, 0.14);
  --mvu-hud-line-strong: rgba(118, 226, 255, 0.34);
  --mvu-hud-panel: rgba(8, 17, 25, 0.78);
  --mvu-hud-panel-soft: rgba(255, 255, 255, 0.045);
  --mvu-hud-text: rgba(240, 250, 252, 0.96);
  --mvu-hud-muted: rgba(183, 211, 222, 0.78);
  font-family: var(--font-ui);
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  text-rendering: optimizeLegibility;
}

