  --mvu-quest-accent-border: color-mix(in srgb, var(--边线颜色) 56%, transparent);
  --mvu-quest-track: color-mix(in srgb, var(--主题主色) 14%, transparent);
  --mvu-quest-card-bg:
    linear-gradient(180deg, color-mix(in srgb, var(--暗场底板强) 72%, transparent), color-mix(in srgb, var(--暗场底板) 64%, transparent)),
