  border-radius: 0;
  border: 0;
  background: transparent;
  box-shadow: none;
  isolation: isolate;
}

.mvu-quest-tab {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 0;
  width: 100%;
