  height: 30px;
  min-height: 30px;
  padding: 0;
  border-radius: var(--mvu-radius-sm, 8px);
  border: 1px solid color-mix(in srgb, var(--边线颜色) 28%, transparent);
  background: color-mix(in srgb, var(--暗场底板强) 86%, transparent);
  color: color-mix(in srgb, var(--文字主色) 72%, transparent);
