.mvu-quest-bookmark,
.mvu-quest-entry-card {
  position: relative;
  display: grid !important;
  gap: 5px;
  min-height: 78px !important;
  padding: 10px 10px 10px 15px !important;
  border-radius: var(--mvu-radius-sm, 8px) !important;
  border: 0;
  border-left: 4px solid color-mix(in srgb, var(--边线颜色) 42%, transparent);
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.012)),
