  box-shadow: var(--mvu-quest-card-shadow);
  cursor: pointer;
  overflow: hidden;
  transition:
    border-color 0.18s ease,
    background 0.18s ease,
    box-shadow 0.18s ease,
    transform 0.18s ease;
}

.mvu-quest-bookmark::before {
  content: '';
  position: absolute;
  inset: 8px auto 8px 3px;
  width: 1px;
  border-radius: var(--mvu-radius-pill, 999px);
  background: transparent;
  box-shadow: 0 0 0 transparent;
}

.mvu-quest-bookmark[data-quest-status='active'] {
  border-left-color: var(--主题主色);
}

.mvu-quest-bookmark[data-quest-status='completed'] {
  border-left-color: #68ff88;
}

.mvu-quest-bookmark[data-quest-status='failed'] {
