}

.mvu-quest-bookmark:hover,
.mvu-quest-bookmark:focus-visible {
  border-color: color-mix(in srgb, var(--边线颜色) 72%, transparent);
  outline: none;
  transform: translateY(-1px);
  box-shadow:
    0 10px 18px rgba(0, 0, 0, 0.16),
    inset 0 1px 0 var(--mvu-color-panel-muted, rgba(255, 255, 255, 0.05));
