.mvu-quest-bookmark.active {
  border-left-color: var(--mvu-quest-accent);
  background: linear-gradient(
    90deg,
    color-mix(in srgb, var(--mvu-quest-accent) 12%, var(--暗场底板强)),
    color-mix(in srgb, var(--暗场底板) 58%, transparent)
  );
  box-shadow:
    0 0 18px var(--mvu-quest-accent-glow),
    inset 0 1px 0 var(--mvu-color-panel-muted, rgba(255, 255, 255, 0.05));
}

.mvu-quest-bookmark.active::before {
  background: var(--mvu-quest-accent);
  box-shadow: 0 0 16px var(--mvu-quest-accent-glow);
}

.mvu-quest-bookmark.is-urgent,
.mvu-quest-bookmark.is-overdue {
  border-left-color: #ef4444;
}

.mvu-quest-bookmark.is-urgent::after {
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  background: linear-gradient(90deg, rgba(239, 68, 68, 0.08), transparent 58%);
  animation: mvuQuestUrgentPulse 3.2s ease-in-out infinite var(--mvu-holo-loop-play-state, running);
}

.mvu-quest-bookmark.is-overdue {
  background:
    linear-gradient(90deg, rgba(244, 63, 94, 0.12), rgba(255, 255, 255, 0.012)),
    rgba(22, 5, 9, 0.72);
}

@keyframes mvuQuestUrgentPulse {
  0%,
  100% {
    opacity: 0.45;
  }
  50% {
    opacity: 1;
  }
}

.mvu-quest-card-top {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  padding-left: 10px;
}

.mvu-quest-card-title {
  min-width: 0;
  flex: 1 1 auto;
  color: var(--文字主色);
  font-size: var(--mvu-font-md, 14px);
  line-height: 1.3;
  font-weight: 900;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvu-quest-card-status {
  flex: 0 0 auto;
  padding: 2px 8px;
  border-radius: var(--mvu-radius-xs, 4px);
  color: color-mix(in srgb, var(--文字主色) 94%, transparent);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.2;
  font-weight: 800;
  white-space: nowrap;
}

.mvu-quest-bookmark[data-quest-status='active'] .mvu-quest-card-status {
  border: 1px solid color-mix(in srgb, var(--主题主色) 30%, transparent);
  background: color-mix(in srgb, var(--主题主色) 10%, transparent);
  color: var(--主题主色);
}

.mvu-quest-bookmark[data-quest-status='completed'] .mvu-quest-card-status {
  border: 1px solid rgba(104, 255, 136, 0.3);
  background: rgba(104, 255, 136, 0.1);
  color: #68ff88;
}

.mvu-quest-bookmark[data-quest-status='failed'] .mvu-quest-card-status {
  border: 1px solid rgba(255, 94, 122, 0.3);
  background: rgba(255, 94, 122, 0.1);
  color: #ff5e7a;
}

.mvu-quest-card-sub {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
  padding-left: 10px;
  color: color-mix(in srgb, var(--文字主色) 70%, var(--文字弱色));
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvu-quest-card-sub span {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
}

.mvu-quest-card-foot {
  padding-left: 10px;
  color: color-mix(in srgb, var(--文字弱色) 84%, transparent);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.35;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvu-quest-card-contract {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding-left: 10px;
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.3;
  font-weight: 900;
  white-space: nowrap;
}

.mvu-quest-card-gain {
  color: #34d399;
  text-shadow: 0 0 8px rgba(16, 185, 129, 0.24);
}

.mvu-quest-card-risk,
.mvu-quest-card-deadline.is-urgent,
.mvu-quest-card-deadline.is-overdue {
  color: #ef4444;
  text-shadow: 0 0 8px rgba(239, 68, 68, 0.28);
}

.mvu-quest-card-deadline {
  flex: 0 0 auto;
  color: color-mix(in srgb, var(--文字主色) 84%, transparent);
  font-size: var(--mvu-font-xs, 10px);
  font-weight: 900;
}

.mvu-quest-mini-progress {
  width: calc(100% - 10px);
  height: 2px;
  margin-left: 10px;
  border-radius: 2px;
  overflow: hidden;
  background: var(--资源槽底);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.055),
    inset 0 0 9px rgba(0, 0, 0, 0.28);
}

.mvu-quest-mini-progress > span {
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--资源槽填充);
  box-shadow: var(--资源槽辉光);
  transition: width 0.3s ease-out;
}

.mvu-quest-detail-shell {
  display: grid;
  gap: 14px;
  min-width: 0;
  align-content: start;
}

.mvu-quest-detail-header {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
  padding-bottom: 10px;
  border-bottom: 1px solid var(--mvu-color-line-soft, rgba(255, 255, 255, 0.08));
}

.mvu-quest-detail-heading {
  display: grid;
  gap: 4px;
  min-width: 0;
}

.mvu-quest-detail-kicker {
  min-width: 0;
  color: var(--mvu-quest-accent);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.2;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.mvu-quest-detail-title {
  min-width: 0;
  color: var(--文字主色);
  font-size: var(--mvu-font-xl, 18px);
  line-height: 1.18;
  font-weight: 900;
  letter-spacing: 0;
}

.mvu-quest-detail-progress {
  margin: 2px 0 0;
  display: grid;
  gap: 7px;
  min-width: 0;
  padding: 0;
  border-radius: 0;
  border: 0;
  background: transparent;
}

.mvu-quest-detail-progress-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 8px;
  color: var(--主题主色);
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.4;
  font-weight: 700;
}

.mvu-quest-detail-progress-track {
  position: relative;
  height: 5px;
  border-radius: 2px;
  overflow: visible;
  border: 0;
  background: var(--资源槽底);
  box-shadow:
    inset 0 0 0 1px rgba(255, 255, 255, 0.055),
    inset 0 0 9px rgba(0, 0, 0, 0.28);
}

.mvu-quest-detail-progress-track::after {
  content: '';
  position: absolute;
  inset: 0;
  background: repeating-linear-gradient(
    45deg,
    transparent,
    transparent 4px,
    rgba(0, 0, 0, 0.3) 4px,
    rgba(0, 0, 0, 0.3) 8px
  );
  pointer-events: none;
}

.mvu-quest-detail-progress-fill {
  position: relative;
  display: block;
  height: 100%;
  border-radius: inherit;
  background: var(--资源槽填充);
  box-shadow: var(--资源槽辉光);
  transition: width 0.4s ease-out;
}

.mvu-quest-detail-progress-fill::after {
  content: '';
  position: absolute;
  top: 50%;
  right: -3px;
  width: 7px;
  height: 7px;
  border-radius: var(--mvu-radius-pill, 999px);
  background: #fff;
  box-shadow: 0 0 12px var(--mvu-quest-accent);
  transform: translateY(-50%);
}

.mvu-quest-meta-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px 18px;
  min-width: 0;
}

.mvu-quest-meta-row {
  display: grid;
  grid-template-columns: minmax(72px, auto) minmax(0, 1fr);
  align-items: baseline;
  gap: 8px;
  min-width: 0;
  padding: 0 0 8px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.055);
  border-radius: 0;
  border-top: 0;
  border-left: 0;
  border-right: 0;
  background: transparent;
}

.mvu-quest-meta-row > span {
  color: color-mix(in srgb, var(--文字弱色) 84%, transparent);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.2;
  font-weight: 800;
}

.mvu-quest-meta-row > b {
  min-width: 0;
  color: color-mix(in srgb, var(--文字主色) 96%, transparent);
  font-size: var(--mvu-font-base, 13px);
  line-height: 1.35;
  font-weight: 800;
  overflow-wrap: anywhere;
}

.mvu-quest-meta-grid--board {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.mvu-quest-deadline-row {
  grid-column: 1 / -1;
}

.mvu-quest-deadline-row.is-urgent > b,
.mvu-quest-deadline-row.is-overdue > b {
  color: #ef4444;
  text-shadow: 0 0 10px rgba(239, 68, 68, 0.24);
}

.mvu-quest-deadline-row > b {
  color: color-mix(in srgb, var(--文字主色) 90%, transparent);
  text-shadow: none;
}

.mvu-quest-contract-panel {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 10px;
  min-width: 0;
}

.mvu-quest-contract-panel--reward-only {
  grid-template-columns: minmax(0, 1fr);
}

.mvu-quest-contract-side {
  display: grid;
  gap: 8px;
  min-width: 0;
  padding: 11px 12px;
  border-radius: var(--mvu-radius-sm, 8px);
  border: 1px solid transparent;
}

.mvu-quest-contract-side strong {
  color: color-mix(in srgb, var(--文字主色) 78%, transparent);
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.2;
  font-weight: 800;
}

.mvu-quest-contract-side > div {
  display: grid;
  gap: 6px;
}

.mvu-quest-contract-side span {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  gap: 8px;
  min-width: 0;
}

.mvu-quest-contract-side em {
  color: color-mix(in srgb, var(--文字弱色) 78%, transparent);
  font-size: var(--mvu-font-xs, 10px);
  line-height: 1.2;
  font-style: normal;
  font-weight: 800;
}

.mvu-quest-contract-side b {
  font-size: var(--mvu-font-lg, 16px);
  line-height: 1.1;
  font-weight: 950;
  font-variant-numeric: tabular-nums;
}

.mvu-quest-contract-side--gain {
  border-color: rgba(16, 185, 129, 0.16);
  background: rgba(16, 185, 129, 0.055);
}

.mvu-quest-contract-side--gain b {
  color: #10b981;
  text-shadow: 0 0 12px rgba(16, 185, 129, 0.28);
}

.mvu-quest-contract-side--risk {
  border-color: rgba(244, 63, 94, 0.16);
  background: rgba(244, 63, 94, 0.055);
}

.mvu-quest-contract-side--risk b {
  color: #f43f5e;
  text-shadow: 0 0 12px rgba(244, 63, 94, 0.28);
}

.mvu-quest-detail-section {
  display: grid;
  gap: 8px;
  padding: 0;
  background: transparent;
  border: 0;
  border-radius: 0;
  margin-bottom: 6px;
}

.mvu-quest-detail-section-title {
  color: color-mix(in srgb, var(--文字弱色) 86%, transparent);
  font-size: var(--mvu-font-sm, 12px);
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.mvu-quest-detail-text {
  min-width: 0;
  color: color-mix(in srgb, var(--文字主色) 96%, transparent);
  font-size: var(--mvu-font-md, 14px);
  line-height: 1.6;
  white-space: pre-wrap;
  overflow-wrap: anywhere;
}

.mvu-quest-detail-actions {
  margin-top: auto;
}

.mvu-quest-detail-card > .mvu-quest-action-bar {
  align-self: end;
  display: flex;
  justify-content: flex-end;
  align-items: center;
  gap: 8px;
  min-width: 0;
  padding-top: 10px;
  border-top: 1px solid rgba(255, 255, 255, 0.07);
  background: linear-gradient(180deg, transparent, color-mix(in srgb, var(--暗场底板强) 58%, transparent));
}

.mvu-quest-detail-card > .mvu-quest-action-bar .mvu-quest-primary-action {
  border-color: color-mix(in srgb, var(--主题主色) 34%, transparent);
  background: linear-gradient(180deg, color-mix(in srgb, var(--主题主色) 88%, var(--主题高光) 12%), color-mix(in srgb, var(--主题主色) 72%, #000 28%));
  color: color-mix(in srgb, var(--主题底色) 86%, #000);
  box-shadow: 0 0 18px color-mix(in srgb, var(--主题主色) 20%, transparent);
  font-weight: 950;
}

.mvu-quest-detail-card > .mvu-quest-action-bar .mvu-quest-primary-action:hover,
.mvu-quest-detail-card > .mvu-quest-action-bar .mvu-quest-primary-action:focus-visible {
  box-shadow: 0 0 24px color-mix(in srgb, var(--主题主色) 34%, transparent);
}

.mvu-quest-detail-card > .mvu-quest-action-bar .mvu-quest-danger-action {
  border-color: rgba(244, 63, 94, 0.18);
  background: rgba(9, 16, 22, 0.52);
  color: color-mix(in srgb, var(--文字主色) 70%, transparent);
  box-shadow: none;
}

.mvu-quest-detail-card > .mvu-quest-action-bar .mvu-quest-danger-action:hover,
.mvu-quest-detail-card > .mvu-quest-action-bar .mvu-quest-danger-action:focus-visible {
  border-color: rgba(244, 63, 94, 0.5);
  background: rgba(244, 63, 94, 0.12);
  color: #f43f5e;
}

.mvu-quest-detail-empty {
  display: grid;
  place-items: center;
  min-height: 160px;
  padding: 18px;
  border-radius: var(--mvu-radius-sm, 8px);
  border: 1px solid color-mix(in srgb, var(--边线颜色) 18%, transparent);
  background: var(--全息材质底);
  color: color-mix(in srgb, var(--文字弱色) 76%, transparent);
  font-size: var(--mvu-font-base, 13px);
  line-height: 1.5;
  text-align: center;
}

.mvu-detail-stack-gap {
  margin-top: 12px;
}

.mvu-detail-relation-tile {
  display: grid !important;
  align-content: start;
  justify-content: stretch !important;
  gap: 6px;
  min-height: 96px;
}

.mvu-detail-relation-value {
  color: var(--cyan) !important;
  font-size: var(--mvu-font-lg, 16px) !important;
  font-weight: 700;
  line-height: 1.35 !important;
}

.mvu-detail-relation-note {
  color: var(--color-text-secondary);
  font-size: var(--mvu-font-sm, 12px);
  line-height: 1.45;
  overflow-wrap: anywhere;
}

@media (max-width: 760px) {
  .mvu-quest-workbench {
    grid-template-columns: 1fr;
    grid-template-rows: auto minmax(0, 1fr);
    gap: 12px;
    overflow: hidden;
  }

  .mvu-quest-summary-bar {
    grid-template-columns: minmax(0, 1fr);
    min-height: 0;
    padding: 9px 10px;
  }

  .mvu-quest-summary-stats {
    justify-content: flex-start;
    flex-wrap: wrap;
    gap: 8px 10px;
  }

  .mvu-quest-summary-stats span {
    text-align: left;
  }

  .mvu-quest-tab-row {
    position: relative;
    top: auto;
    left: auto;
    order: 2;
    z-index: 1;
    display: grid;
    grid-template-columns: repeat(3, minmax(0, 1fr));
    flex-direction: initial;
    gap: 4px;
    min-width: 0;
    width: 100%;
    padding: 4px;
    border-radius: var(--mvu-radius-md, 12px);
  }

  .mvu-quest-list-card > .archive-card-head {
    order: 1;
  }

  .mvu-quest-list-card > .mvu-quest-workbench {
    order: 3;
  }

  .mvu-quest-tab {
    width: 100%;
    min-width: 0;
    height: 38px;
    min-height: 38px;
    justify-content: flex-start;
    gap: 8px;
    padding: 0 8px;
    border-radius: var(--mvu-radius-sm, 8px);
    transition: background 0.2s, border-color 0.2s, box-shadow 0.2s, color 0.2s;
  }

  .mvu-quest-tab:hover,
  .mvu-quest-tab:focus-visible,
  .mvu-quest-tab.is-active {
    width: 100%;
  }

  .mvu-quest-tab-mark {
    flex-basis: 18px;
    width: 18px;
    height: 18px;
    font-size: var(--mvu-font-sm, 12px);
  }

  .mvu-quest-tab-label,
  .mvu-quest-tab:hover .mvu-quest-tab-label,
  .mvu-quest-tab:focus-visible .mvu-quest-tab-label,
  .mvu-quest-tab.is-active .mvu-quest-tab-label {
    position: static;
    width: auto;
    height: auto;
    overflow: hidden;
    clip: auto;
    min-width: 0;
    opacity: 1;
    transform: none;
    font-size: var(--mvu-font-sm, 12px);
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  .mvu-quest-tab-count,
  .mvu-quest-tab:hover .mvu-quest-tab-count,
  .mvu-quest-tab:focus-visible .mvu-quest-tab-count,
  .mvu-quest-tab.is-active .mvu-quest-tab-count {
    position: static;
    display: inline-flex;
    align-items: center;
    justify-content: center;
    transform: none;
    margin-left: auto;
    min-width: 18px;
    padding: 2px 6px;
    border-radius: var(--mvu-radius-pill, 999px);
    border: 1px solid color-mix(in srgb, var(--边线颜色) 28%, transparent);
    background: color-mix(in srgb, var(--暗场底板强) 68%, transparent);
    color: color-mix(in srgb, var(--文字主色) 82%, transparent);
    font-size: var(--mvu-font-xs, 10px);
    line-height: 1.2;
    font-weight: 800;
    opacity: 1;
  }

  .archive-card-head > .mvu-quest-create-panel .mvu-detail-form-row {
    left: 12px;
    right: 12px;
    width: auto;
    max-height: min(58svh, 420px);
  }

  .mvu-quest-form-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .mvu-quest-form-field--full {
    grid-column: 1;
  }

  .mvu-quest-meta-grid,
  .mvu-quest-meta-grid--board {
    grid-template-columns: minmax(0, 1fr);
  }

  .mvu-quest-meta-row {
    grid-template-columns: minmax(64px, auto) minmax(0, 1fr);
  }

  .mvu-quest-contract-panel {
    grid-template-columns: minmax(0, 1fr);
  }

  .mvu-quest-detail-card > .mvu-quest-action-bar {
    justify-content: flex-start;
    flex-wrap: wrap;
  }

  .mvu-quest-detail-card > .mvu-quest-action-bar > button {
    min-width: 0;
    max-width: 100%;
  }
}
