body.mvu-layout-holo #mvu-unified-mount .mvu-unified-frame {
  position: relative;
  box-sizing: border-box;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr);
  gap: 0;
  width: 100%;
  height: var(--mvu-hud-frame-height, 620px);
  min-height: 0;
  max-height: var(--mvu-hud-frame-height, 620px);
  overflow: hidden;
  isolation: isolate;
  border: 1px solid transparent;
  border-radius: var(--投影圆角);
  clip-path: var(--面板裁切);
  background:
