    var(--面板远距辉光),
    inset 0 0 22px color-mix(in srgb, var(--主题主色) 10%, transparent);
  backdrop-filter: var(--虚化强度);
  -webkit-backdrop-filter: var(--虚化强度);
  color: var(--mvu-holo-text);
  font-family: var(--主题字体);
  font-weight: var(--主题字重);
  perspective: 1200px;
  pointer-events: auto;
}

body.mvu-layout-holo #mvu-unified-mount .mvu-unified-frame::before {
  content: "";
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  border-radius: inherit;
  background: var(--面板光层);
  opacity: 0.52;
}

