  0% {
    opacity: 0;
    transform: translateY(-14px) scaleY(0.94) translateZ(0);
  }
  55% {
    opacity: 1;
    transform: translateY(0) scaleY(1.015) translateZ(0);
  }
  100% {
    opacity: 1;
    transform: translateY(0) scaleY(1) translateZ(0);
  }
