  0% {
    opacity: 0;
    transform: scaleX(1.08) translateX(-10px) translateZ(0);
  }
  20% {
    opacity: 1;
    transform: scaleX(0.96) translateX(8px) translateZ(0);
  }
  42% {
    opacity: 0.58;
    transform: scaleX(1.025) translateX(-4px) translateZ(0);
  }
  62% {
    opacity: 1;
    transform: scaleX(1) translateX(0) translateZ(0);
  }
  78% {
    opacity: 0.82;
  }
  100% {
    opacity: 1;
    transform: scaleX(1) translateX(0) translateZ(0);
  }
}

