  0% {
    opacity: 1;
    transform: translateX(0) translateZ(0);
  }
  55% {
    opacity: 0.55;
    transform: translateX(-8px) translateZ(0);
  }
  100% {
    opacity: 0;
    transform: translateX(12px) translateZ(0);
  }
}

